output_text:
[
  {
    "id": "use_entry_cart",
    "text": "A shopper should take the available entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_station": "at(1,5)",
        "entry_cart_available": "cartAt(1,5)"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_station",
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "items_go_in_cart",
    "text": "Items should be picked up only while the shopper is pushing a cart, not while shopping by hand.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart",
        "carrying_by_hand": "handFull",
        "not_using_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cart_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cart_in_use"
            ]
          },
          "post": "hasCart"
        },
        "hand_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "or": [
                  "not_using_cart",
                  "carrying_by_hand"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_item_pickup"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the designated cart bay before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_bay_cell": "at(0,1)",
        "cart_parked_in_bay": "cartAt(0,1)",
        "cart_in_use": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_bay_cell",
              "cart_in_use",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_cart_abandonment",
    "text": "A shopper must not leave a cart anywhere except the designated cart-return bay.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "outside_cart_return_bay": {
          "not": "at_cart_return_bay"
        }
      },
      "events": {
        "abandon_cart_off_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_off_bay"
    }
  },
  {
    "id": "no_exit_with_burden",
    "text": "The shopper must not exit the store while still pushing a cart or carrying an item by hand.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "carrying_item_by_hand": "handFull",
        "burdened": {
          "or": [
            "pushing_cart",
            "carrying_item_by_hand"
          ]
        }
      },
      "events": {
        "burdened_exit": {
          "pre": {
            "and": [
              "EXIT",
              "burdened"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "burdened_exit"
    }
  },
  {
    "id": "must_drop_cart_at_bay",
    "text": "Upon reaching the cart-return bay while pushing a cart, the shopper should not move away with the cart instead of dropping it.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "ready_to_return_cart": {
          "and": [
            "at_cart_return_bay",
            "pushing_cart"
          ]
        }
      },
      "events": {
        "move_away_with_cart_from_bay": {
          "pre": {
            "and": [
              "ready_to_return_cart",
              "MOVE"
            ]
          },
          "post": "hasCart"
        },
        "drop_cart_at_bay": {
          "pre": {
            "and": [
              "ready_to_return_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_away_with_cart_from_bay"
    }
  },
  {
    "id": "no_shopping_after_return",
    "text": "After the cart has been returned to the bay, the shopper should not resume item pickup.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)",
        "cartless_after_return": {
          "and": [
            "cart_returned",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_item_pickup": {
          "pre": {
            "and": [
              "cartless_after_return",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_item_pickup"
    }
  },
  {
    "id": "do_not_retake_returned_cart",
    "text": "Once a cart is parked in the return bay, the shopper should not pick that cart up again.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "returned_cart_available": {
          "and": [
            "cart_parked_in_return_bay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "retake_returned_cart": {
          "pre": {
            "and": [
              "returned_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  }
]
